INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(94185, 'ruRU', 'Вечная печаль — вот всё, что тебя ждёт.', '', 24330),
(94186, 'ruRU', 'Я, Даглоп Милоскверн, Даглоп Великозлобный, Даглоп Чудовский, явился заключить сделку!', '', 24330),
(94187, 'ruRU', 'Прочитать контракт.', '', 24330),
(94188, 'ruRU', 'Подписать контракт кровью.', '', 24330),
(94189, 'ruRU', 'Контракт начинается с крупного, витиеватого, мерзкого на вид почерка, который с каждым предложением становится всё мельче и мельче. Он начинается так:$b$bСтраница 1:$b«Я, нижеподписавшийся, далее именуемый „вторая сторона“, торжественно клянусь и соглашаюсь с условиями, изложенными Даглопом Равалиашем Дрисколом Блатом, далее именуемым „Даглоп“».', '', 24330),
(94190, 'ruRU', 'Перейти к странице 2.', '', 24330),
(94191, 'ruRU', 'Перейти к странице 3.', '', 24330),
(94192, 'ruRU', 'Перейти к странице 1.', '', 24330),
(94193, 'ruRU', 'Контракт продолжается всё более мелким шрифтом:$b$bСтраница 2:$b«Эти условия включают добычу материалов, необходимых для ритуала Шаразаан, далее именуемого „заказ“, а также истребление, устранение, убиение или умерщвление субъектов, живых или иных, которые препятствуют вышеупомянутым ресурсам, необходимым для заказа и Даглопа».', '', 24330),
(94194, 'ruRU', 'Буквы теперь почти неразличимы:$b$bСтраница 3:$b«Взамен Даглоп соглашается предоставить второй стороне физически неосязаемый источник энергии Скверны для наделения силой одного артефакта великой мощи, находящегося во владении упомянутой второй стороны, далее именуемого „награда“».', '', 24330),
(94195, 'ruRU', 'Перейти к странице 4.', '', 24330),
(94196, 'ruRU', 'Страница 4:$b«По завершении заказа вышеупомянутая награда, предназначенная для второй стороны, должна быть предоставлена посредством прямого извлечения из третьей стороны, роль которой исполнит цель -»$b$bК этому моменту буквы становятся настолько мелкими, что фактически нечитаемы для смертных глаз.', '', 24330),
(94197, 'ruRU', 'Преклонись перед Хелирой.', '', 24330),
(94198, 'ruRU', 'Ты командир? Прошу, умоляю, выслушай меня, на кону судьба Дренора! Гулдан нашёл его! Он нашёл Шифр!', '', 24330),
(94199, 'ruRU', 'Ксалитар пал! Как такое возможно?!', '', 24330),
(94200, 'ruRU', 'У друидов не должно было быть такой силы! Гатенак убит!', '', 24330),
(94201, 'ruRU', 'Кто мог убить Ксалитара?!', '', 24330),
(94202, 'ruRU', 'Они убили Гатенака!', '', 24330),
(94203, 'ruRU', 'Говори быстрее, чернокнижник.', '', 24330),
(94204, 'ruRU', 'Гулдан намерен использовать Шифр Проклятия, чтобы осквернить сами стихии Дренора. Он выжжет все эти джунгли адским пламенем.$b$bТолько сейчас я вижу всю глубину его безумия и ненависти.$b$bБыстрее! Гулдан узнал о шаманах-хранителях, защищающих Шифр. Он движется, чтобы атаковать их оплот. Кто-то должен защитить их.', '', 24330),
(94205, 'ruRU', 'Я отправлюсь немедленно.', '', 24330),
(94207, 'ruRU', 'Чуешь этот морской воздух! Как приятно снова оказаться в открытом море.', '', 24330),
(94208, 'ruRU', 'Помогите! Гулдан... он внутри!', '', 24330),
(94209, 'ruRU', 'Преклонись перед богиней Хелией.', '', 24330),
(94211, 'ruRU', 'Защищай меня, пока я разрываю эту связь с Круговертью Пустоты!', '', 24330),
(94212, 'ruRU', 'Я нарушу стабильность портала. Сдерживайте демонов, пока я работаю!', '', 24330),
(94215, 'ruRU', '$GHe:She; попался на это!', '', 24330),
(94216, 'ruRU', 'Думал, это будет так просто?', '', 24330),
(94217, 'ruRU', 'Это наше сокровище, уродливый $r!', '', 24330),
(94218, 'ruRU', 'Ха! Попался!', '', 24330),
(94219, 'ruRU', 'Уверен, тот платёж из Оргриммара тут совсем ни при чём.', '', 24330);
